/// <summary>
/// DebuC 23.08.21 Req 3654 Task 4545
///     find NDXItemUsageIds Record by ItemUsageId
/// </summary>
/// <param name="_id">NDXItemUsageId</param>
/// <param name="_forUpdate">boolean</param>
/// <returns>record of NDXItemUsageIds</returns>
static KCS_ItemUsageIds find(KCS_ItemUsageId _id, boolean _forUpdate = false)
{
    KCS_ItemUsageIds itemUsageIds;

    itemUsageIds.selectForUpdate(_forUpdate);

    select firstonly itemUsageIds
    where itemUsageIds.KCS_ItemUsageId == _id;

    return itemUsageIds;
}

/// <summary>
///
/// </summary>
/// <param name = "_fieldId"></param>

public void modifiedField(FieldId _fieldId)
{
    InventTable inventTable, inventTableGroupBy;
    int         counter = 0;

    super(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(KCS_ItemUsageIds, IsCatalogItem):
            if(Box::yesNo(strFmt("@NDX:NDXChangedItemUsageValue", this.KCS_ItemUsageId, this.IsCatalogItem), DialogButton::No) == DialogButton::Yes)
            {                  
                while select crosscompany inventTableGroupBy
                    group by inventTableGroupBy.DataAreaId
                {
                    changecompany(inventTableGroupBy.DataAreaId)
                    {
                        inventTable = null;

                        while select forupdate inventTable
                        where inventTable.KCS_ItemUsageId == this.KCS_ItemUsageId
                        {
                            inventTable.KCS_IsCatalogItem = this.IsCatalogItem;
                            if(inventTable.validateWrite())
                            {
                                inventTable.update();
                                counter++;
                            }
                        }
                    }
                }
                Info(strFmt("@NDX:NDXItemsHasBeenChanged", counter));
            }
            break;
    }
}
